import { Search, type SearchProps } from "@components/search";
import { clsx } from "clsx";

import { useTable } from "../hooks/use-table";
import { TableClasses } from "../table.styles";

export const TableSearch = ({
  className,
  onQueryChange,
  value,
  children,
  "aria-label": ariaLabel = "Search table",
  ...props
}: SearchProps) => {
  const table = useTable();
  const globalFilter = table.getState().globalFilter;

  return (
    <Search
      className={clsx(TableClasses.searchInput, className)}
      openOnClick={false}
      {...props}
      value={value !== undefined ? value : globalFilter || ""}
      onQueryChange={(query: SearchProps["query"]) => {
        table.setGlobalFilter(query);
        onQueryChange?.(query);
      }}
    >
      {children || (
        <Search.Input aria-label={ariaLabel}>
          <Search.InputPrefix />
          <Search.InputSuffix>
            <Search.ClearIconButton />
          </Search.InputSuffix>
        </Search.Input>
      )}
    </Search>
  );
};

TableSearch.displayName = "Table.Search";
